using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using IndianOceanAssets.ShooterSurvival; public static class PopcornInspect16{public static object Main(){var setup=EditorSceneManager.GetSceneManagerSetup();try{EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/ShoeTower.unity");var r=UnityEngine.Object.FindObjectsByType<Chapter45RoleAction>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(x=>x.role==Chapter45RoleAction.Role.PopcornThrower);return new{heldProp=r.heldProp.name,binding=EditorJsonUtility.ToJson(r.heldProp.GetComponent<Chapter45HandProps>()),children=r.heldProp.Cast<Transform>().Select(t=>new{t.name,pos=t.localPosition.ToString("R"),scale=t.localScale.ToString("R"),mesh=t.GetComponent<MeshFilter>()==null?null:t.GetComponent<MeshFilter>().sharedMesh.name}).ToArray(),projectile=r.projectileTemplate.name,projectilePersistent=EditorUtility.IsPersistent(r.projectileTemplate),template=EditorJsonUtility.ToJson(r.projectileTemplate.GetComponent<SimpleProjectile>()),scale=r.projectileTemplate.transform.localScale.ToString("R"),components=r.projectileTemplate.GetComponents<Component>().Select(x=>x.GetType().Name).ToArray()};}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}}}